const items = $input.all();
const results = [];

for (const item of items) {
  const data = item.json;

  // Kandidat
  if (data.property_geburtsdatum) {
    let maxDistanz = 50;
    let debug_found_field = 'NICHT GEFUNDEN';
    let debug_found_value = null;

    // Suche speziell nach dem Feld 'gewünschte distanz'
    for (const key of Object.keys(data)) {
      if (key.toLowerCase().includes('gew') && key.toLowerCase().includes('nschte')) {
        debug_found_field = key;
        debug_found_value = data[key];
        const match = String(data[key]).match(/\d+/);
        if (match) {
          maxDistanz = parseInt(match[0]);
          break;
        }
      }
    }

    results.push({
      json: {
        id: data.id,
        name: data.property_name,
        address: data.property_wohnadresse,
        lat: data.property_latitude,
        lng: data.property_longitude,
        max_distanz_km: maxDistanz,
        debug_field: debug_found_field,
        debug_value: debug_found_value,
        type: 'kandidat',
        has_coords: (data.property_latitude !== null && data.property_latitude !== undefined && data.property_longitude !== null && data.property_longitude !== undefined)
      }
    });
  }
  // Fachgeschäft
  else if (data.property_adresse) {
    results.push({
      json: {
        id: data.id,
        name: data.property_name,
        address: data.property_adresse,
        lat: data.property_latitude,
        lng: data.property_longitude,
        type: 'shop',
        has_coords: (data.property_latitude !== null && data.property_latitude !== undefined && data.property_longitude !== null && data.property_longitude !== undefined)
      }
    });
  }
}

return results;

// Kombinierter Geocoding + Cache Handler
const items = $input.all();
const results = [];
const toSave = [];

for (const item of items) {
  const data = item.json;

  // Hat bereits Koordinaten - Cache verwenden
  if (data.has_coords && data.lat && data.lng) {
    results.push(item);
    continue;
  }

  // Braucht Geocoding
  try {
    const response = await fetch(`https://maps.googleapis.com/maps/api/geocode/json?address=${encodeURIComponent(data.address)}&key=AIzaSyB_s5jbJR1VBCXP_bPe84DgtDTT6wulaIc`);
    const geo = await response.json();

    if (geo.status === 'OK' && geo.results[0]) {
      const loc = geo.results[0].geometry.location;

      // Koordinaten zum Item hinzufügen
      const newItem = {
        json: {
          ...data,
          lat: loc.lat,
          lng: loc.lng,
          has_coords: true
        }
      };

      results.push(newItem);

      // Markieren zum Speichern in Notion
      toSave.push({
        id: data.id,
        lat: loc.lat,
        lng: loc.lng
      });
    }
  } catch (error) {
    // Bei Fehler: Item ohne Koordinaten durchlassen
    results.push(item);
  }
}

// Koordinaten in Notion speichern
for (const save of toSave) {
  try {
    await fetch(`https://api.notion.com/v1/pages/${save.id}`, {
      method: 'PATCH',
      headers: {
        'Authorization': 'Bearer ntn_U25383296342JvfPTKO32BPxyT6cbVAL3e3AJnFuXUX3tI',
        'Notion-Version': '2022-06-28',
        'Content-Type': 'application/json'
      },
      body: JSON.stringify({
        properties: {
          'Latitude': { number: save.lat },
          'Longitude': { number: save.lng }
        }
      })
    });
  } catch (error) {
    // Fehler beim Speichern ignorieren - Koordinaten sind trotzdem im Workflow verfügbar
  }
}

return results;

const all = $input.first().json.data;
const kandidaten = all.filter(x => x.type === 'kandidat');
const shops = all.filter(x => x.type === 'shop');

function distance(lat1, lon1, lat2, lon2) {
  const R = 6371;
  const dLat = (lat2-lat1) * Math.PI/180;
  const dLon = (lon2-lon1) * Math.PI/180;
  const a = Math.sin(dLat/2)**2 + Math.cos(lat1*Math.PI/180) * Math.cos(lat2*Math.PI/180) * Math.sin(dLon/2)**2;
  return R * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1-a));
}

const results = [];

for (const k of kandidaten) {
  // Sicherstellen dass max_distanz_km ein valider Wert ist
  const maxDist = Number(k.max_distanz_km);
  if (!maxDist || isNaN(maxDist)) continue;

  // Koordinaten prüfen
  if (!k.lat || !k.lng) continue;

  const nearby = [];

  for (const s of shops) {
    if (!s.lat || !s.lng) continue;

    const d = distance(k.lat, k.lng, s.lat, s.lng);
    const distKm = Math.round(d*10)/10;

    // Expliziter Vergleich mit Nummer
    if (d <= maxDist) {
      nearby.push({ id: s.id, name: s.name, dist: distKm });
    }
  }

  nearby.sort((a,b) => a.dist - b.dist);

  if (nearby.length > 0) {
    const text = nearby.map((x,i) => `${i+1}. ${x.name}: ${x.dist} km`).join('\n');

    results.push({
      json: {
        kandidat_name: k.name,
        kandidat_id: k.id,
        shop_ids: nearby.map(x => x.id),
        min_dist: nearby[0].dist,
        comment: 'Zugeordnete Geschäfte:\n' + text
      }
    });
  }
}

return results;
